from pathlib import Path
import numpy as np,json
w=Path(__file__).resolve().parent;z=np.load(w/'long_settled_tomato.npz');x=z['x'];v=z['v'];dt=np.float32(1.5e-7);free=np.setdiff1d(np.arange(len(x)),z['fixed']);increment=np.float32(v*dt);new=np.float32(x+increment);effective=(new.astype(float)-x.astype(float))/float(dt);mask=np.abs(v[free])>.001;frozen=(new[free]==x[free]);out={'scope':'Offline one-position-update calculation at final velocity; no subsequent forces/integration or long-run causal attribution','dt_s':float(dt),'coordinate_dtype':str(x.dtype),'free_velocity_components_over_1mm_s':int(mask.sum()),'such_components_rounded_to_zero_position_increment':int((mask&frozen).sum()),'fraction':float((mask&frozen).sum()/max(1,mask.sum())),'max_reported_node_speed_m_s':float(np.linalg.norm(v[free],axis=1).max()),'max_effective_minus_reported_speed_norm_m_s':float(np.linalg.norm(effective[free]-v[free],axis=1).max()),'toy_float32_example':{'position_m':.05,'velocity_m_s':.01,'computed_next_equals_current':bool(np.float32(.05)+np.float32(.01)*dt==np.float32(.05))},'interpretation':'Very small steps can round nonzero velocities to zero stored position increments. This is an identified precision limit, not permission to discard or relax the velocity settling gate.'};(w/'position_precision_check.json').write_text(json.dumps(out,indent=2));print(json.dumps(out,indent=2))
